      'content_contract_version',6,
      'search_intent_questions',jsonb_build_array('ما هي تقنية Boundary Making؟','ما الفرق بين الحدود وBoundary Making؟','كيف يستخدم المعالج المكان لتغيير التفاعل؟','كيف تنظم التقنية العلاقة بين الوالد والطفل؟','ما علاقتها بـEnactment؟','هل تستخدم مع الأسرة الممتدة؟','كيف نقيس نجاح تغيير الحدود؟','متى لا تكون المواجهة المباشرة آمنة؟'),
      'claim_source_map',jsonb_build_array(
        jsonb_build_object('claim','مفهوم الحدود يمكن تفكيكه إلى القرب والهرمية وينبغي فهمه بصورة مرنة وغير مرضية تلقائيًا','sources',jsonb_build_array('boundaries-transition-1983')),
        jsonb_build_object('claim','التقييم البنيوي لدى الخبراء ينتقل من المشكلة الفردية إلى التفاعلات التي تحفظها ويستخدم تقنيات متعددة لإعادة الصياغة النظامية','sources',jsonb_build_array('structural-assessment-2013')),
        jsonb_build_object('claim','تحليل محادثي للعلاج البنيوي أظهر إعادة ضبط أدوار الأم والابنة داخل جلسة باستخدام موارد تفاعلية مرتبطة بإعادة الهيكلة','sources',jsonb_build_array('change-family-therapy-2020')),
        jsonb_build_object('claim','دراسة حالة بنيوية وصفت تعديل الحدود والهرمية ضمن تدخل أسري مع تحسن وظيفي ملحوظ','sources',jsonb_build_array('structural-case-2021')),
